{
  "highlights": [
    {
      "start_time": 0,
      "end_time": 5000,
      "description": "两只白狐抬着轿子来到石屋前，化作两名白衣男子跪地喊王老爹救命。"
    },
    {
      "start_time": 49000,
      "end_time": 65000,
      "description": "瘫痪在床三年的石墩见到门外的金子，竟挣扎着爬下床站起身，王老爹震惊不已。"
    },
    {
      "start_time": 279000,
      "end_time": 290000,
      "description": "巨树树根破土而出攻击三人，白衣男子伸手抵挡时露出非人的利爪，王老爹惊觉他不是人类。"
    },
    {
      "start_time": 343000,
      "end_time": 361000,
      "description": "山洞外的群狐纷纷化作人形，对着持杖狼神跪拜，原来他是鹰崖山的山神，护佑一山生灵。"
    },
    {
      "start_time": 516000,
      "end_time": 521000,
      "description": "白狐老祖被救活，满洞狐狸齐齐跪拜，齐声感谢王老爹的救命之恩。"
    },
    {
      "start_time": 204000,
      "end_time": 218000,
      "description": "前路被雪豹和群兽拦住，灰衣男子称它们不敢上前，果然雪豹伏地让路，两人抬轿走过处泛起绿光。"
    },
    {
      "start_time": 582000,
      "end_time": 586000,
      "description": "狼神用拐杖点开石门，里面堆满了奇珍异宝，竟是狐族的宝库。"
    },
    {
      "start_time": 588000,
      "end_time": 598000,
      "description": "白狐老祖让王老爹随意拿取宝库中的宝物，王老爹直言救命是救命，拿东西是两码事，分文不取。"
    },
    {
      "start_time": 522000,
      "end_time": 530000,
      "description": "之前咬过王老爹的黑狐执刑官，凑过来舔舐王老爹手上的伤口认错，王老爹又气又笑。"
    },
    {
      "start_time": 471000,
      "end_time": 488000,
      "description": "黑狐执刑官不信任王老爹，咬住他的手臂阻拦救治，王老爹直言再拖老祖就没命了，任由它撕咬。"
    },
    {
      "start_time": 323000,
      "end_time": 328000,
      "description": "三人登上悬崖顶，王老爹一眼认出了传说中的九味还魂草，惊喜不已。"
    },
    {
      "start_time": 312000,
      "end_time": 318000,
      "description": "两名白衣男子架着王老爹，在近乎垂直的冰崖上飞速攀登，王老爹吓得惊呼这不是人走的路。"
    },
    {
      "start_time": 72000,
      "end_time": 98000,
      "description": "石墩抱着金子哭求父亲上山救人，说自己瘫了三年被人看不起，只要去一趟家里就能翻身。"
    },
    {
      "start_time": 117000,
      "end_time": 123000,
      "description": "王老爹思虑再三，丢下手中的菜刀，长叹一声“罢了好歹是条命”，答应跟两人上山救人。"
    },
    {
      "start_time": 176000,
      "end_time": 184000,
      "description": "王老爹掀轿帘查看，发现厚雪地上两名抬轿人走路竟没有留下脚印，顿时疑心这趟活不对劲。"
    },
    {
      "start_time": 27000,
      "end_time": 33000,
      "description": "白衣男子倒出满满一堆金元宝作为谢礼，称只要能救活老祖，还会有更多酬谢。"
    },
    {
      "start_time": 33000,
      "end_time": 37000,
      "description": "王老爹看着满地金子，称来路不明的金子自己不敢收，拒绝了两人的请求。"
    },
    {
      "start_time": 225000,
      "end_time": 232000,
      "description": "王老爹看到前方悬崖上长着一棵满是红眼睛的巨树，吓得连忙喊停，说自己不去了要回家。"
    },
    {
      "start_time": 387000,
      "end_time": 404000,
      "description": "王老爹进洞时石缝突然合拢，吓得他大喊洞要吃人，狼神解释是洞府在尝他的气息，歹人进来会被碾成肉泥。"
    },
    {
      "start_time": 432000,
      "end_time": 435000,
      "description": "洞府里的小白狐们站在石臼旁，熟练地捣着草药，模样十分灵动。"
    },
    {
      "start_time": 436000,
      "end_time": 450000,
      "description": "一群绿眼黑狐从暗处走出，乃是洞府的执刑官，若有人对老祖不利，便不会让他活着走出洞口。"
    },
    {
      "start_time": 536000,
      "end_time": 542000,
      "description": "白狐老祖苏醒过来，坐起身对着王老爹行礼，尊称他为恩公。"
    },
    {
      "start_time": 608000,
      "end_time": 614500,
      "description": "白衣男子将一袋子金元宝倒在王老爹面前，王老爹看着满地金子，震惊得说不出话。"
    },
    {
      "start_time": 561000,
      "end_time": 570000,
      "description": "王老爹救完老祖后，唯一的要求就是让狐族送自己回家，担心家里瘫着的儿子。"
    },
    {
      "start_time": 7000,
      "end_time": 12000,
      "description": "深夜有人敲门，王老爹举着菜刀开门查看，以为是贼人上门。"
    }
  ],
  "hook": [
    {
      "start_time": 279000,
      "end_time": 290000,
      "description": "巨树的树根突然破土而出攻击三人，白衣男子伸手抵挡时，手竟变成了长着利爪的妖爪，王老爹见状震惊失色，脱口说出那不是人的手。",
      "hook_type": "身份悬念",
