    },
    {
      "start_time": 471000,
      "end_time": 488000,
      "description": "王老爹正要救治重伤的白狐老祖，黑狐执刑官因不信任外人，死死咬住王老爹的手臂阻拦，王老爹直言再拖下去老祖就没命了，任由黑狐撕咬。",
      "hook_type": "冲突悬念",
      "open_question": "黑狐执刑官会不会松口，允许王老爹继续救治白狐老祖？",
      "end_point_reason": "已成立：黑狐执刑官咬住王老爹的手臂阻拦他救治老祖；未展开：黑狐是否会松口允许王老爹救人。"
    },
    {
      "start_time": 494000,
      "end_time": 500500,
      "description": "王老爹为白狐老祖拔出毒箭后，发现毒素仍残留在肉里，直言就算拔了箭，老祖也照样活不过今晚。",
      "hook_type": "结果悬念",
      "open_question": "王老爹有没有办法清除毒素，救活白狐老祖？",
      "end_point_reason": "已成立：王老爹拔箭后发现毒素未清，称老祖活不过今晚；未展开：王老爹能否治好老祖的毒伤。"
    },
    {
      "start_time": 176000,
      "end_time": 184000,
      "description": "王老爹坐在轿中赶路，掀帘发现厚雪地上，两个抬轿的年轻人走路竟没有留下任何脚印，顿时心生疑虑，觉得这趟活不对劲。",
      "hook_type": "身份悬念",
      "open_question": "两名抬轿的年轻人究竟是什么来历？为什么在雪地里走路不会留下脚印？",
      "end_point_reason": "已成立：王老爹发现两名抬轿人在厚雪地上走路没有脚印；未展开：两名抬轿人的真实身份是什么。"
    },
    {
      "start_time": 542000,
      "end_time": 554000,
      "description": "白狐老祖告知王老爹，自己中了专伤精怪根骨的乌头毒箭，王老爹询问射箭者是谁，老祖只回答是“贪心人”，未透露更多信息。",
      "hook_type": "身份悬念",
      "open_question": "射伤白狐老祖的“贪心人”究竟是什么身份？",
      "end_point_reason": "已成立：白狐老祖称射伤自己的是“贪心人”，未透露其具体身份；未展开：“贪心人”的真实身份是什么。"
    },
    {
      "start_time": 578000,
      "end_time": 614500,
      "description": "王老爹拒绝了狐族宝库中的所有珍宝，白狐老祖称不能让恩公空手而归，命人将一袋金元宝倒在王老爹面前，王老爹见状震惊得说不出话。",
      "hook_type": "利益期待",
      "open_question": "王老爹最终会不会收下这袋作为谢礼的金元宝？",
      "end_point_reason": "已成立：白狐老祖为答谢王老爹救命之恩，命人将一袋金元宝倒在他面前；未展开：王老爹是否会收下这袋金元宝。"
    },
    {
      "start_time": 49000,
      "end_time": 65000,
      "description": "瘫痪在床三年、医治无效的石墩，见到门外的金子后竟挣扎着爬下床，甚至站了起来，王老爹见状震惊不已，不敢相信自己的眼睛。",
      "hook_type": "信息悬念",
      "open_question": "石墩的瘫痪到底是真的还是假装的？",
      "end_point_reason": "已成立：瘫痪三年的石墩见到金子后竟能自行站起；未展开：石墩的瘫痪是否为真。"
    }
  ]
